using NUnit.Framework;

[TestFixture]
public class FindSmallestEvenTests
{
    [Test]
    public void Returns_Smallest_Even()
    {
        var result = FindSmallestEven(new[] { 8, 3, 10, 2, 14 });
        Assert.That(result, Is.EqualTo(2));
    }

    private int? FindSmallestEven(int[] nums)
    {
        int? best = null;

        foreach (var num in nums)
        {
            if (num % 2 == 0 && (best == null || num < best))
                best = num;
        }

        return best;
    }
}
